const getFavoritedAudioIDs = `-- name: GetFavoritedAudioIDs :many
;

select audio_id
from audio_favorite
where user_id = ?1 and audio_id in (/*SLICE:ids*/?)
`

type GetFavoritedAudioIDsParams struct {
	Uid string   `json:"uid"`
	Ids []string `json:"ids"`
}

func (q *Queries) GetFavoritedAudioIDs(ctx context.Context, arg GetFavoritedAudioIDsParams) ([]string, error) {
	query := getFavoritedAudioIDs
	var queryParams []interface{}
	queryParams = append(queryParams, arg.Uid)
	if len(arg.Ids) > 0 {
		for _, v := range arg.Ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(arg.Ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var audio_id string
		if err := rows.Scan(&audio_id); err != nil {
			return nil, err
		}
		items = append(items, audio_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

