const upsertAudioRating = `-- name: UpsertAudioRating :one
;

insert into audio_rating (audio_id, user_id, rating, rated_at)
values (?, ?, ?, datetime('now'))
on conflict (audio_id, user_id) do update set
    rating = excluded.rating,
    rated_at = excluded.rated_at
returning audio_id, user_id, rating, rated_at
`

type UpsertAudioRatingParams struct {
	AudioID string `json:"audio_id"`
	UserID  string `json:"user_id"`
	Rating  int64  `json:"rating"`
}

func (q *Queries) UpsertAudioRating(ctx context.Context, arg UpsertAudioRatingParams) (AudioRating, error) {
	row := q.db.QueryRowContext(ctx, upsertAudioRating, arg.AudioID, arg.UserID, arg.Rating)
	var i AudioRating
	err := row.Scan(
		&i.AudioID,
		&i.UserID,
		&i.Rating,
		&i.RatedAt,
	)
	return i, err
}
